// EdgeModels is the resolver for the EdgeModels field.
func (r *queryResolver) EdgeModels(ctx context.Context) ([]*model.ModelInfo, error) {
	token := GatewayTokenFromContext(ctx)
	if token == nil {
		return nil, fmt.Errorf("unauthorized")
	}

	txn := dbstore.DBINS.NewTransaction()
	defer txn.Rollback()

	// 使用当前用户地址作为 caller 创建 runtime，以便 GetProviderByOwner 能正确识别
	runtime := contracts.NewRuntimeWithVersion(0, time.Now(), txn, token.Addr, chaintypes.UniAddr{}, module.NativeVersion)

	ins := gateway.NewGateway(runtime)
	query := gateway.GatewayQuery{Gateway: *ins}

	// 查询当前用户的 provider ID
	opt, err := query.GetProviderByOwner()
	if err != nil {
		return nil, err
	}
	if opt.IsNone() {
		return []*model.ModelInfo{}, nil
	}
	providerID, err := opt.UnWrap()
	if err != nil {
		return nil, err
	}

	// 获取该 provider 下的所有模型
	models, err := query.ListProviderModels(providerID)
	if err != nil {
		return nil, err
	}

	// 过滤 providerType == 9999 的本地模型
	result := make([]*model.ModelInfo, 0, len(models))
	for _, mid := range models {
		m := mid.Data
		if m.ProviderType == 9999 {
			result = append(result, &model.ModelInfo{
				Name:            m.Name,
				ProviderID:      int(m.ProviderID),
				ProviderType:    int(m.ProviderType),
				ModelID:         m.ModelID,
				URI:             m.URI,
				InputModalities: int(m.InputModalities),
				ContextLength:   int(m.ContextLength),
				InPrice:         int(m.InPrice),
				CachedPrice:     int(m.CachedPrice),
				OutPrice:        int(m.OutPrice),
				IsActive:        m.IsActive,
				CreatedAt:       int(m.CreatedAt),
			})
		}
	}

	return result, nil
}

